entries.example:
var Text = "{""number"":""A-17"",""lines"":[{""item"":""Paper"",""qty"":2}]}";
var Reader = New JSONReader(Text);
var Order = Reader.ReadValue();
Message(Order.number + ": " + Order.lines.Count());
foreach (Line In Order.lines) {
    Message(Line.item + " x " + Line.qty);
}

var Reader = New JSONReader("{""a"":1,""b"":2}");
while (Reader.Read()) {
    if (Reader.CurrentValueType = JSONValueType.PropertyName) {
        Message(Reader.CurrentValue);      // a, then b
    }
}

var Reader = New JSONReader("{""qty"":0.1}");
Reader.Read();                             // {
Reader.Read();                             // the name
Message(Reader.CurrentValue);              // qty
Reader.Read();                             // the number
Message(Reader.CurrentValue + 0.2);        // 0.3 exactly

var Reader = New JSONReader();
Reader.SetString(Answer);
var Result = Reader.ReadValue();

var Reader = New JSONReader("[1,2,3]");
Reader.Read();                             // [
var Sum = 0;
while (Reader.Read() And Reader.CurrentValueType <> JSONValueType.ArrayEnd) {
    Sum = Sum + Reader.ReadValue();
}
Message(Sum);                              // 6

var Reader = New JSONReader(Text);
var Lines = Undefined;
while (Reader.Read()) {
    if (Reader.CurrentValueType = JSONValueType.PropertyName) {
        if (Reader.CurrentValue = "lines") {
            Lines = Reader.ReadValue();
        } elseif (Reader.CurrentValue = "meta") {
            Reader.Skip();                 // the name and its value, in one step
        }
    }
}

var Reader = New JSONReader("{""total"":0.1,""paid"":true,""note"":null}");
var Order = Reader.ReadValue();
Message(Order.total + 0.2);                // 0.3 exactly
Message(Order.paid);
Message(Order.note = Null);

var Reader = New JSONReader(Text);
var Order = Reader.ReadValue();
Reader.Close();      // a 30 MB message is not held any longer than it is needed

